use serde_json::{json, Value};

pub(super) fn storage() -> Vec<Value> {
    vec![
        json!({"type":"function","function":{"name":"storage_analyze","description":"Analyze a user-selected directory without modifying files. Returns a cancellable storage_scan task; poll task_progress for the report. Reports logical and filesystem-allocated bytes, suffix categories and largest files; NOT reclaimable space or application cache. No symlink traversal or cross-filesystem recursion. Use full root only for an explicitly requested directory.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"},"maxEntries":{"type":"integer","minimum":1,"maximum":100000}},"additionalProperties":false}}}),
    ]
}

pub(super) fn operations() -> Vec<Value> {
    vec![
        json!({"type":"function","function":{"name":"files_pending","description":"List pending user confirmation proposals; this does not approve or execute them.","parameters":{"type":"object","properties":{},"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_delete","description":"Prepare file, symlink or recursive directory deletion; deleting a symlink removes only the link, never its target. Parent symlinks are rejected. Returns an approval proposal; does NOT delete until the user confirms in the app. Do not claim deletion completed or bypass approval via shell.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"},"recursive":{"type":"boolean"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_prepare_overwrite","description":"Prepare an explicit overwrite approval for streaming upload, text editing or URL download. Optional expectedSha256 requires unchanged existing contents up to 2 MiB. App user must approve; this tool alone does not grant permission.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"},"expectedSha256":{"type":"string"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"task_start","description":"Start large-file streaming transfer within the selected root; download may follow ordinary links bounded to that root, upload parents must not contain links. Uploads fall back to exclusive-create copy after checksum verification when shared storage lacks atomic no-replace; the destination may be visible while committing. Download hashes in background and becomes ready. Upload requires expected size and SHA-256. HTTP data path is returned; poll task_progress. Existing files are never overwritten.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"direction":{"type":"string","enum":["download","upload"]},"path":{"type":"string"},"sizeBytes":{"type":"integer","minimum":0},"sha256":{"type":"string"},"overwriteToken":{"type":"string"}},"required":["direction","path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"task_progress","description":"Read file transfer phase, byte progress, SHA-256 and final result.","parameters":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"task_cancel","description":"Cancel an unfinished transfer and clean its temporary upload. Completed files remain.","parameters":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_preview","description":"Open a short-lived read-only range stream for a user-selected regular file or ordinary symlink resolving within the selected root. Does not launch a target player or download the whole file. Release the returned id with files_preview_close.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_preview_close","description":"Release one file preview resource. Does not modify the source file or close a target player's media resource.","parameters":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_download","description":"Snapshot a regular file or bounded ordinary file link within the selected root, up to 16 MiB. Returns a short-lived binary download path and SHA-256, never file contents as text. Use task_start for large-file streaming.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_url_info","description":"Read the suggested filename and optional size of an HTTP(S) URL from the target using response headers; does not save a file.","parameters":{"type":"object","properties":{"url":{"type":"string"}},"required":["url"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_download_url","description":"Download an HTTP(S) URL directly on the target. Optional root (default downloads), relative directory (default root), and name (default URL final segment or download.bin). Returns a url_download background task; poll task_progress and cancel with task_cancel. On a name collision returns conflict metadata and a suggested name without starting a task. Overwrite requires a separately user-approved overwriteToken.","parameters":{"type":"object","properties":{"url":{"type":"string"},"root":{"type":"string","enum":["downloads","inbox","full"]},"directory":{"type":"string"},"name":{"type":"string"},"overwriteToken":{"type":"string"}},"required":["url"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_rename","description":"Rename one file, folder or symbolic link within its existing directory. Never overwrites an existing name. Parent symlinks and moving across directories are rejected; renaming a link changes the link itself.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"},"name":{"type":"string"}},"required":["path","name"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_mkdir","description":"Create one new directory inside the selected root. Parent must exist; relative paths only. Does not overwrite existing entries, follow symlinks, create parents or change permissions of existing paths.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_list","description":"List a directory in Downloads, service inbox or explicitly selected full filesystem root. Relative paths only; ordinary symlinks may be followed for read-only access within the selected root. Entries report symlink targets/errors; linked directories are read-only. Cursor is the last filename of a previous page.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"},"cursor":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":100}},"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_stat","description":"Read metadata of a relative path inside the selected root, including bounded symlink target and failure details.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"additionalProperties":false}}}),
    ]
}
